// Three everyday leak patterns and their fixes.

// 1) Timer leak: the closure captures a big payload forever.
let cache = null
function startPollingBad(data) {
  setInterval(() => {
    cache = expensiveTransform(data) // interval never cleared: data + cache retained
  }, 1000)
}
function startPollingGood(data) {
  const id = setInterval(() => {
    cache = expensiveTransform(data)
  }, 1000)
  return () => clearInterval(id) // caller must invoke on teardown
}

// 2) Listener leak: emitter outlives the component.
store.on("change", handler)            // added...
// ...and never removed when the view closes
store.off("change", handler)           // the fix: symmetric removal

// 3) Unbounded cache: Map grows with every user visited.
const badCache = new Map()             // 100k users = 100k entries forever
const keyedCache = new WeakMap()       // entry dies with its key object
function memoize(obj) {
  if (!keyedCache.has(obj)) keyedCache.set(obj, compute(obj))
  return keyedCache.get(obj)
}
